/// Helpers for laying out generated Swift so `swift format` leaves it unchanged.
enum SourceText {
    private static let lineLength = 140

    /// The first lines of every generated file.
    static func header(from sources: [CatalogSource]) -> [String] {
        let catalogs = sources.map(\.snapshotPath).joined(separator: ", ")
        return ["// Generated by ModelCatalogGenerator from \(catalogs). Don't edit.", ""]
    }

    /// An array literal after `prefix`: on one line when it fits, otherwise one element per line.
    static func array(_ prefix: String, _ elements: [String], indent: String, suffix: String = "") -> [String] {
        let oneLine = "\(indent)\(prefix)[\(elements.joined(separator: ", "))]\(suffix)"
        guard oneLine.count >= lineLength else { return [oneLine] }
        return ["\(indent)\(prefix)["] + elements.map { "\(indent)    \($0)," } + ["\(indent)]\(suffix)"]
    }

    /// A list for prose, such as "`a`, `b` and `c`".
    static func prose(_ words: [String]) -> String {
        let quoted = words.map { "`\($0)`" }
        guard let last = quoted.last, quoted.count > 1 else { return quoted.first ?? "" }
        return quoted.dropLast().joined(separator: ", ") + " and " + last
    }

    /// The file's text: its lines joined, with one final newline.
    static func file(_ lines: [String]) -> String {
        lines.joined(separator: "\n") + "\n"
    }
}
